-- 068: titles and descriptions within the display limit in ca, es, fr and da.
--
-- 066 did this for English. German was already inside the limit, because the
-- German pass respected it. The other four were not: average title lengths of
-- 75, 79, 82 and 69 characters against English's 52, and average descriptions
-- of 190, 194, 196 and 166 against 149. Google truncates a title past roughly
-- 60 and a description past roughly 155, so on those four languages the
-- reader deciding whether to click was being shown a sentence that stops
-- mid-word.
--
-- Eight native writers, two per language, worked from the corrected English
-- and the current translation, with the instruction to write what their
-- language would write rather than translate the English headline. French
-- needed the most restructuring, as expected from the longest average.
--
-- The passes also picked up things a length brief was not looking for, and
-- those are kept: Catalan words inside the Spanish text, "Neurotisisme",
-- "grupdetænkning", "konfliktvigelse" and "Højydende" in Danish,
-- "extraversion introversion" run together in Spanish, decimal points where
-- the language uses a comma, and Cercol dimension names still in English in
-- fields 065 did not touch.
--
-- Every value was length-checked, dash-checked and round-tripped through
-- json.loads before this file was written, and the assertions at the end
-- check the shape of the columns rather than only counting violations.
-- See 067 for why that distinction matters.

BEGIN;

UPDATE blog_posts SET title = title || '{"ca": "16Personalities vs Big Five: el test que encerta a mitges", "es": "16Personalities vs Big Five: el test que acierta a medias", "fr": "16Personalities vs Big Five : le test à moitié juste", "da": "16Personalities vs Big Five: testen der har halvt ret"}'::jsonb, description = description || '{"ca": "16Personalities hereta el defecte central del MBTI: tipus en lloc d''espectres. Vet aquí què fa el Big Five en el seu lloc, i per què importa.", "es": "Cientos de millones han hecho 16Personalities, que hereda el fallo del MBTI: tipos en vez de espectros. Esto es lo que hace el Big Five.", "fr": "Passé par des centaines de millions de personnes, 16Personalities hérite du défaut du MBTI : des types au lieu de spectres. Le Big Five fait autrement."}'::jsonb, updated_at = now()
 WHERE slug = '16personalities-vs-big-five-the-viral-test-that-gets-it-half-right';
UPDATE blog_posts SET title = title || '{"ca": "L''amabilitat a la feina: el cost de ser massa agradable", "es": "La Amabilidad en el trabajo: el coste oculto de ser amable"}'::jsonb, description = description || '{"ca": "L''amabilitat a la feina prediu cooperació, però també penalització salarial i evitació del conflicte. El cost real d''un Vincle elevat.", "es": "La Amabilidad predice cooperación, pero también castigo salarial y huida del conflicto. El coste real de un Vínculo alto en el trabajo.", "fr": "L''Agréabilité au travail prédit la coopération, mais aussi une pénalité salariale et l''évitement des conflits. Le vrai coût d''un Lien élevé.", "da": "Venlighed på jobbet giver samarbejde, men også lønstraf og konfliktskyhed. Her er den reelle pris for høj Tilknytning på arbejdspladsen."}'::jsonb, updated_at = now()
 WHERE slug = 'agreeableness-at-work-the-hidden-cost-of-being-too-nice';
UPDATE blog_posts SET title = title || '{"ca": "L''anonimat en els tests de personalitat: per què importa", "es": "Anonimato en la evaluación de personalidad: por qué importa", "fr": "Pourquoi l''anonymat compte dans les tests de personnalité", "da": "Anonymitet i personlighedstest: hvorfor det betyder noget"}'::jsonb, description = description || '{"ca": "L''avaluació d''alt risc infla la Conscienciositat mitja desviació estàndard. Per què el context distorsiona les puntuacions i com hi respon Cèrcol.", "es": "La evaluación con consecuencias infla la Responsabilidad media desviación típica. Por qué el contexto distorsiona las puntuaciones en Cèrcol.", "fr": "L''anonymat réduit le biais de désirabilité sociale et améliore la qualité des données. Pourquoi les conditions de passation changent la précision.", "da": "Vurdering med høj indsats oppuster Samvittighedsfuldhed med en halv standardafvigelse. Her er, hvorfor kontekst forvrider scorer, og hvad Cèrcol gør."}'::jsonb, updated_at = now()
 WHERE slug = 'anonymity-in-personality-assessment-why-it-matters';
UPDATE blog_posts SET title = title || '{"ca": "Millors tests de personalitat gratuïts per a equips 2026", "es": "Mejores tests de personalidad gratis para equipos en 2026", "fr": "Meilleurs tests de personnalité gratuits pour équipes 2026", "da": "De bedste gratis personlighedstests til teams i 2026"}'::jsonb, description = description || '{"ca": "Hi ha dotzenes de tests de personalitat gratuïts i pocs amb suport científic real. Quines eines Big Five són vàlides el 2026, i quines no.", "es": "Hay docenas de tests de personalidad gratuitos y pocos con respaldo científico. Qué herramientas Big Five son válidas en 2026, y cuáles no.", "fr": "Des dizaines de tests gratuits existent, peu ont un socle scientifique. Le classement 2026 des outils Big Five valides, et de ceux qui ne le sont pas.", "da": "Der findes dusinvis af gratis personlighedstests, men få har reel videnskab bag sig. Her er, hvilke Big Five-værktøjer der holder i 2026, og hvilke ikke."}'::jsonb, updated_at = now()
 WHERE slug = 'best-free-personality-tests-for-teams-2026';
UPDATE blog_posts SET title = title || '{"ca": "El Big Five a través de les cultures: què diu la recerca", "es": "El Big Five a través de las culturas", "fr": "Le Big Five est-il universel ? Les preuves interculturelles", "da": "Big Five på tværs af kulturer: hvad forskningen viser"}'::jsonb, description = description || '{"ca": "L''estructura del Big Five es replica en 51 cultures, però les mitjanes de l''OCEAN difereixen per regió. Què mostra la recerca transcultural.", "es": "¿Se sostiene el Big Five en todo el mundo? La estructura se replica en 51 culturas, pero las medias del OCEAN cambian según la región.", "fr": "La structure du Big Five se réplique dans 51 cultures, mais les scores moyens OCEAN diffèrent selon les régions. Ce que cela change pour les équipes."}'::jsonb, updated_at = now()
 WHERE slug = 'big-five-personality-across-cultures-what-research-shows';
UPDATE blog_posts SET description = description || '{"ca": "Big Five, DISC i Belbin diuen que expliquen el comportament d''equip. Només un té 50 anys d''evidència transcultural revisada per experts.", "es": "Big Five, DISC y Belbin dicen explicar la conducta del equipo. Solo uno tiene 50 años de evidencia transcultural revisada por pares.", "fr": "Big Five, DISC et Belbin promettent tous d''expliquer le comportement en équipe. Un seul a 50 ans de preuves transculturelles évaluées par des pairs.", "da": "Big Five, DISC og Belbin vil alle forklare teamadfærd. Kun én har 50+ års tværkulturel, fagfællebedømt evidens bag sig. Her er forskellen."}'::jsonb, updated_at = now()
 WHERE slug = 'big-five-vs-disc-vs-belbin';
UPDATE blog_posts SET title = title || '{"ca": "Punts cecs en equips: quan l''autopercepció no coincideix", "es": "Puntos ciegos en equipos: cuando el autoinforme falla", "fr": "Angles morts en équipe : quand soi et les pairs divergent", "da": "Blinde vinkler: når selvbillede og peer-vurdering afviger"}'::jsonb, description = description || '{"ca": "L''autoinforme i l''avaluació entre iguals del Big Five divergeixen més en el Neuroticisme. On són els punts cecs, i per què desgasten l''equip.", "es": "El autoinforme y la evaluación de pares divergen sobre todo en Neuroticismo (r = 0,20 a 0,40). Esos puntos ciegos erosionan la coordinación.", "fr": "Les scores Big Five auto-déclarés et ceux des pairs divergent le plus sur le Névrosisme (r = 0,20 à 0,40). Ces angles morts minent l''équipe.", "da": "Selvrapport og peer-vurdering af Big Five afviger mest på Neuroticisme. Her er, hvor de blinde vinkler opstår, og hvad de koster et team."}'::jsonb, updated_at = now()
 WHERE slug = 'blind-spots-in-teams';
UPDATE blog_posts SET title = title || '{"ca": "Crear un equip de zero: els límits de les dades Big Five", "es": "Crear un equipo desde cero: los límites del Big Five", "fr": "Constituer une équipe : les limites des données Big Five", "da": "Byg et team fra bunden: grænserne for Big Five-data"}'::jsonb, description = description || '{"ca": "Les dades Big Five revelen bretxes en la composició de l''equip, però no l''encaix cultural ni la química. Són una entrada, no un filtre.", "es": "Los datos Big Five revelan huecos en la composición del equipo, no el encaje cultural ni la química. Úsalos como insumo, no como filtro.", "fr": "Les données Big Five révèlent les manques de composition, pas l''adéquation culturelle ni la chimie. Un intrant de décision, pas un filtre de recrutement.", "da": "Big Five-data afslører huller i teamsammensætningen, men ikke kemi, kulturel pasform eller vækst. Brug det som input, ikke som ansættelsesfilter."}'::jsonb, updated_at = now()
 WHERE slug = 'building-a-team-from-scratch-what-personality-data-can-and-cant-tell-you';
UPDATE blog_posts SET title = title || '{"ca": "Construir seguretat psicològica amb dades de personalitat", "es": "Seguridad psicológica y ciencia de la personalidad", "fr": "Sécurité psychologique et science de la personnalité", "da": "Psykologisk sikkerhed og personlighedsvidenskaben"}'::jsonb, description = description || '{"ca": "La seguretat psicològica varia segons el perfil Big Five. El Neuroticisme necessita constància; l''Amabilitat, permís per dissentir.", "es": "La seguridad psicológica varía según el perfil Big Five: el Neuroticismo pide constancia y la Amabilidad, permiso para disentir.", "fr": "La sécurité psychologique varie selon le profil Big Five : le Névrosisme demande de la constance, l''Agréabilité le droit de contredire. Les preuves.", "da": "Psykologisk sikkerhed varierer med Big Five-profilen. Neuroticisme kræver forudsigelighed, Venlighed kræver lov til at være uenig. Her er evidensen."}'::jsonb, updated_at = now()
