UPDATE blog_posts SET title = title || '{"ca": "Pot canviar la personalitat? Coaching, teràpia i evidència", "es": "¿Se puede cambiar la personalidad? Coaching y terapia", "fr": "La personnalité peut-elle changer ? Coaching et thérapie", "da": "Kan personlighed ændres? Coaching- og terapiforskningen"}'::jsonb, description = description || '{"ca": "La personalitat pot canviar, però menys del que promet l''autoajuda. Què mostra la recerca de coaching i teràpia sobre el canvi del Big Five.", "es": "La personalidad cambia, pero menos de lo que promete la autoayuda. Qué muestra la investigación en coaching y terapia sobre el cambio Big Five.", "fr": "La personnalité change, mais moins que ne le promet le développement personnel. Ce que la recherche sur le coaching et la thérapie montre du Big Five.", "da": "Personlighed kan ændre sig, men mindre end selvhjælpsbøger lover. Her er, hvad coaching- og terapiforskningen viser om forandring i Big Five."}'::jsonb, updated_at = now()
 WHERE slug = 'can-personality-be-changed-coaching-therapy-evidence';
UPDATE blog_posts SET title = title || '{"fr": "Peut-on fausser un test de personnalité, et est-ce grave ?"}'::jsonb, description = description || '{"ca": "Falsificar un test de personalitat pot moure les puntuacions mitja desviació estàndard. Si això perjudica la validesa predictiva és discutit.", "es": "Falsear un test de personalidad mueve las puntuaciones media desviación típica. Que eso dañe la validez predictiva es más discutido de lo que parece.", "fr": "Fausser un test peut décaler les scores d''un demi-écart-type. Que cela nuise vraiment à la validité prédictive est bien plus débattu qu''il n''y paraît.", "da": "At forfalske en personlighedstest kan flytte scorer med en halv standardafvigelse. Om det skader forudsigelsesvaliditeten, er mere omstridt end antaget."}'::jsonb, updated_at = now()
