UPDATE blog_posts SET title = title || '{"ca": "Compatibilitat entre cofundadors: la diligència deguda", "es": "Cofundadores: la due diligence de personalidad que falta", "fr": "Cofondateurs : la due diligence de personnalité", "da": "Medstiftere og personlighed: den due diligence ingen laver"}'::jsonb, description = description || '{"ca": "La incompatibilitat entre cofundadors mata més startups que els mals mercats. El Big Five detecta bretxes de Vincle, Disciplina i Visió.", "es": "La incompatibilidad entre cofundadores mata más startups que el mercado. El Big Five señala las brechas de Vínculo, Disciplina y Visión.", "fr": "L''incompatibilité entre cofondateurs tue plus de startups que les mauvais marchés. Le Big Five révèle les écarts de Lien, Discipline et Vision.", "da": "Uenige medstiftere dræber flere startups end dårlige markeder. Big Five viser gabene i Tilknytning, Disciplin og Vision, der forudsiger friktion."}'::jsonb, updated_at = now()
