UPDATE blog_posts SET title = title || '{"ca": "Estils de conflicte i personalitat: què diu l''evidència", "es": "Estilos de resolución de conflictos y personalidad", "fr": "Personnalité et conflits : ce que dit le Big Five"}'::jsonb, description = description || '{"ca": "El Big Five prediu el teu estil de conflicte: l''Amabilitat acomoda, el Neuroticisme evita, l''Obertura col·labora. Açò mostra l''evidència.", "es": "El Big Five predice tu estilo de conflicto: la Amabilidad cede, el Neuroticismo evita y la Apertura colabora. Esto dice la evidencia.", "fr": "Le Big Five prédit votre réflexe en conflit : l''Agréabilité s''accommode, le Névrosisme évite, l''Ouverture collabore. Ce que montrent les données.", "da": "Big Five forudsiger din konfliktstil: Venlighed føjer sig, Neuroticisme undviger, Åbenhed samarbejder. Her er, hvad evidensen faktisk viser."}'::jsonb, updated_at = now()
