UPDATE blog_posts SET title = title || '{"ca": "Conscienciositat: quan la disciplina esdevé perfeccionisme", "es": "Responsabilidad: cuando la disciplina es perfeccionismo", "fr": "Conscienciosité : quand la rigueur vire au perfectionnisme", "da": "Samvittighedsfuldhed: når disciplin bliver perfektionisme"}'::jsonb, description = description || '{"ca": "La Conscienciositat impulsa el rendiment, però les puntuacions extremes deriven en perfeccionisme i rigidesa. On traça la línia el Big Five.", "es": "La Responsabilidad impulsa el rendimiento laboral, pero en su extremo deriva en perfeccionismo y rigidez. Dónde traza la línea el Big Five.", "fr": "La Conscienciosité stimule la performance, mais les scores extrêmes basculent dans le perfectionnisme et la rigidité. Où le Big Five trace la limite.", "da": "Samvittighedsfuldhed driver præstation, men ekstreme scorer tipper over i perfektionisme og stivhed. Her trækker Big Five-forskningen grænsen."}'::jsonb, updated_at = now()
