UPDATE blog_posts SET title = title || '{"ca": "Obertura i creativitat: l''evidència del Big Five", "es": "Apertura y creatividad: la evidencia del Big Five", "fr": "Ouverture et créativité : les preuves du Big Five", "da": "Åbenhed og kreativitet: evidensen fra Big Five"}'::jsonb, description = description || '{"ca": "L''Obertura a l''Experiència és el predictor Big Five més fort de la creativitat. Què mostren de debò les metaanàlisis sobre el treball creatiu.", "es": "La Apertura a la Experiencia es el mayor predictor Big Five de la creatividad. Qué muestran de verdad los metaanálisis del trabajo creativo.", "fr": "L''Ouverture domine la recherche Big Five sur la créativité, mais la Conscienciosité et le Névrosisme comptent aussi. Ce que disent les méta-analyses.", "da": "Åbenhed er den stærkeste Big Five-prædiktor for kreativitet. Her er, hvad metaanalyserne faktisk viser om personlighed og kreativt arbejde."}'::jsonb, updated_at = now()
