UPDATE blog_posts SET title = title || '{"ca": "Crítiques al Big Five: què diuen els crítics", "es": "Críticas al Big Five, explicadas", "fr": "Les critiques adressées au Big Five, expliquées", "da": "Kritikken af Big Five: hvad kritikerne har ret i"}'::jsonb, description = description || '{"es": "El Big Five es el modelo de personalidad más replicado, y aun así tiene críticos serios. Qué dicen de su estructura, su cultura y sus límites.", "fr": "Le Big Five est le modèle de personnalité le plus répliqué, sans être à l''abri des critiques : structure, culture, limites de prédiction.", "da": "Big Five er den mest replikerede personlighedsmodel, men ikke hævet over kritik. Her er, hvad kritikerne siger, og hvor modellen holder stand."}'::jsonb, updated_at = now()
