UPDATE blog_posts SET description = description || '{"ca": "DISC divideix les persones en quatre estils amb validació revisada mínima. El Big Five ofereix cinc dimensions contínues i 50 anys d''evidència.", "es": "DISC reparte a las personas en cuatro estilos con validación mínima. El Big Five ofrece cinco dimensiones continuas y 50 años de evidencia.", "fr": "DISC répartit les gens en quatre styles, presque sans validation. Le Big Five offre cinq dimensions continues et 50 ans de preuves. Voici pourquoi.", "da": "DISC deler mennesker i fire stilarter med minimal validering. Big Five giver fem kontinuerlige dimensioner og 50 års evidens. Her er forskellen."}'::jsonb, updated_at = now()
 WHERE slug = 'disc-vs-big-five-why-four-styles-arent-enough';
UPDATE blog_posts SET title = title || '{"ca": "Existeixen les diferències generacionals de personalitat?", "es": "¿Existen las diferencias generacionales de personalidad?", "fr": "Les générations ont-elles vraiment une personnalité ?", "da": "Findes der generationsforskelle i personlighed?"}'::jsonb, description = description || '{"ca": "«Mil·lennials contra boomers» sona a ciència, però les dades longitudinals del Big Five diuen que les diferències són petites i lligades a l''edat.", "es": "Millennials contra boomers suena a ciencia, pero los datos longitudinales del Big Five dan diferencias pequeñas y confundidas con la edad.", "fr": "Millennials contre boomers : les données longitudinales du Big Five montrent des écarts faibles, confondus avec l''âge et largement fabriqués.", "da": "Millennials mod boomers lyder som videnskab. Longitudinale Big Five-data viser små forskelle, forvekslet med alder og i høj grad skabt af medierne."}'::jsonb, updated_at = now()
