UPDATE blog_posts SET title = title || '{"ca": "Canvia la personalitat al llarg de la vida? L''evidència", "fr": "La personnalité change-t-elle au fil de la vie ?", "da": "Ændrer Big Five-træk sig gennem et helt liv?"}'::jsonb, description = description || '{"ca": "Els trets del Big Five són estables però no fixos. Cinquanta anys de recerca longitudinal: la Conscienciositat puja i el Neuroticisme baixa.", "fr": "Les traits Big Five sont stables sans être figés. Cinquante ans de suivi longitudinal montrent où la Conscienciosité monte et le Névrosisme baisse.", "da": "Big Five-træk er stabile, men ikke faste. Halvtreds års longitudinal forskning viser, at Samvittighedsfuldhed stiger og Neuroticisme falder med alderen."}'::jsonb, updated_at = now()
 WHERE slug = 'do-personality-traits-change-over-a-lifetime';
UPDATE blog_posts SET title = title || '{"es": "¿Predice el rendimiento la personalidad del equipo?", "fr": "La personnalité d''une équipe prédit-elle sa performance ?", "da": "Forudsiger teamets personlighed dets præstation?"}'::jsonb, description = description || '{"es": "¿La mezcla de rasgos Big Five predice cómo rinde un equipo? Qué concluye de verdad un metaanálisis de 60 estudios sobre composición.", "fr": "Le mélange de traits Big Five d''une équipe prédit-il ses résultats ? Ce que conclut vraiment une méta-analyse de 60 études sur la composition.", "da": "Forudsiger blandingen af Big Five-træk i et team, hvordan det præsterer? Det svarer en metaanalyse af 60 studier om teamsammensætning på."}'::jsonb, updated_at = now()
