UPDATE blog_posts SET title = title || '{"ca": "Cinc mites sobre la personalitat que no volen morir", "es": "Cinco mitos sobre la personalidad que no mueren", "fr": "Cinq mythes tenaces sur la science de la personnalité", "da": "Fem myter om personlighedsvidenskab, der ikke vil dø"}'::jsonb, description = description || '{"ca": "Cinc mites sobre la personalitat es resisteixen a morir, de «la personalitat és fixa» a «els tests diuen a qui contractar». Què diu el Big Five.", "es": "Cinco mitos sobre la personalidad se resisten a morir, de «es algo fijo» a «el test dice a quién contratar». Qué muestra el Big Five.", "fr": "Cinq mythes refusent de mourir, de la personnalité figée au test qui dirait qui recruter. Ce que montrent réellement les données du Big Five.", "da": "Fem myter om personlighed nægter at dø, fra »personlighed er fast« til »tests viser, hvem du skal ansætte«. Her er, hvad Big Five-evidensen siger."}'::jsonb, updated_at = now()
