UPDATE blog_posts SET title = title || '{"ca": "Escales de tria forçada: com redueixen la falsificació", "es": "Escalas de elección forzada: así reducen el falseo", "fr": "Échelles à choix forcé : comment elles limitent la triche", "da": "Forced-choice-skalaer: sådan mindsker de forfalskning"}'::jsonb, description = description || '{"ca": "Les escales de tria forçada fan impossible estar d''acord amb tot i retallen el biaix de desitjabilitat. Com funcionen, què costen i quan usar-les.", "es": "Las escalas de elección forzada impiden estar de acuerdo con todo y recortan la deseabilidad social. Cómo funcionan y cuándo conviene usarlas.", "fr": "Le choix forcé rend impossible d''approuver tout, ce qui coupe la désirabilité sociale. Comment il fonctionne, ce qu''il coûte, quand l''utiliser.", "da": "Forced-choice-skalaer gør det umuligt at være enig i alt og skærer social ønskværdighed væk. Sådan virker de, hvad de koster, og hvornår de dur."}'::jsonb, updated_at = now()
