UPDATE blog_posts SET title = title || '{"ca": "De fundador a CEO: una perspectiva de personalitat", "es": "De fundador a CEO: una lectura desde la personalidad", "fr": "De fondateur à PDG : ce que dit la personnalité", "da": "Fra grundlægger til CEO: et personlighedsperspektiv"}'::jsonb, description = description || '{"ca": "El pas de fundador a CEO falla per desajust de personalitat, no de competències: molta Visió i poca Disciplina per a l''etapa d''escalada.", "es": "El paso de fundador a CEO falla por desajuste de personalidad, no de habilidades: mucha Visión y poca Disciplina para escalar la empresa.", "fr": "Les échecs du passage de fondateur à PDG tiennent à la personnalité, pas aux compétences : beaucoup de Vision, pas assez de Discipline.", "da": "Skiftet fra grundlægger til CEO fejler på personlighed, ikke på evner. Høj Vision byggede firmaet, men skalering kræver den Disciplin, der mangler."}'::jsonb, updated_at = now()
