UPDATE blog_posts SET title = title || '{"ca": "Diferències de sexe en el Big Five: l''evidència", "es": "Diferencias de sexo en el Big Five: la evidencia", "fr": "Genre et Big Five : ce que disent vraiment les preuves", "da": "Kønsforskelle i Big Five: hvad evidensen viser"}'::jsonb, description = description || '{"ca": "Les diferències de sexe en els trets del Big Five són reals però petites. Què diu l''evidència metaanalítica sobre gènere i personalitat.", "es": "Las diferencias de sexo en los rasgos Big Five existen, pero son casi siempre pequeñas. Qué dice el metaanálisis sobre género y personalidad.", "fr": "Les différences de genre dans les traits Big Five existent, mais restent petites. Ce que dit la méta-analyse, sans l''emballement médiatique."}'::jsonb, updated_at = now()
 WHERE slug = 'gender-and-personality-what-big-five-research-says';
UPDATE blog_posts SET title = title || '{"ca": "Pensament de grup i personalitat: causes i prevenció", "es": "Pensamiento grupal y personalidad: causas y prevención", "fr": "Pensée de groupe et personnalité : causes et prévention", "da": "Gruppetænkning og personlighed: årsager og forebyggelse"}'::jsonb, description = description || '{"ca": "El pensament de grup colpeja més els equips amb Amabilitat alta i Obertura baixa. El Big Five identifica els perfils de risc i les solucions.", "es": "El pensamiento grupal golpea más fuerte con Amabilidad alta y Apertura baja. El Big Five nombra los perfiles de riesgo y las soluciones.", "fr": "La pensée de groupe frappe surtout les équipes à forte Agréabilité et faible Ouverture. Le Big Five nomme les profils à risque et les correctifs.", "da": "Gruppetænkning rammer hårdest i teams med høj Venlighed og lav Åbenhed. Big Five udpeger risikoprofilerne og de løsninger, der har bedst evidens."}'::jsonb, updated_at = now()
