UPDATE blog_posts SET description = description || '{"ca": "El Big Five va trigar 70 anys a construir-se, d''Allport i Cattell fins a Goldberg. Com el model dels cinc factors va arribar a dominar la psicologia.", "es": "El Big Five tardó 70 años en construirse, de Allport y Cattell a Goldberg. Cómo el modelo de cinco factores acabó dominando la psicología.", "fr": "Le Big Five a mis 70 ans à se construire, d''Allport à Cattell puis Goldberg. Pourquoi cette convergence place le modèle OCEAN devant ses rivaux.", "da": "Big Five tog 70 år at bygge: Allport, Cattell, Goldberg. Den hårdt vundne enighed er grunden til, at OCEAN overlever alle konkurrerende modeller."}'::jsonb, updated_at = now()
