UPDATE blog_posts SET title = title || '{"ca": "Quants Testimonis calen per obtenir dades fiables?", "es": "¿Cuántos Testigos hacen fiables tus datos de personalidad?", "fr": "Combien de Témoins pour des données fiables ?", "da": "Hvor mange Vidner skal der til for pålidelige data?"}'::jsonb, description = description || '{"ca": "Tres Testimonis arriben a una fiabilitat de 0,62; cinc, a 0,73. La fórmula de Spearman-Brown mostra quan afegir-ne més deixa de millorar les dades.", "es": "Tres Testigos alcanzan una fiabilidad de 0,62; cinco llegan a 0,73. Spearman-Brown indica cuándo sumar más Testigos deja de aportar.", "fr": "Trois Témoins atteignent une fiabilité de 0,62 ; cinq montent à 0,73. La formule de Spearman-Brown dit quand en ajouter cesse de servir.", "da": "Tre Vidner giver en reliabilitet på 0,62, fem giver 0,73. Spearman-Brown viser præcis, hvornår flere Vidner holder op med at forbedre dine data."}'::jsonb, updated_at = now()
