UPDATE blog_posts SET title = title || '{"ca": "Com es calculen les puntuacions dels tests de personalitat", "es": "Cómo se puntúa un test de personalidad: del ítem al rasgo", "fr": "Comment se calcule un score de test de personnalité", "da": "Sådan beregnes personlighedstest: fra svar til træk"}'::jsonb, description = description || '{"ca": "Respons 120 preguntes i apareixen les puntuacions Big Five. Com funciona de debò: formats Likert, puntuació inversa, IRT i normalització.", "es": "Respondes 120 preguntas y aparecen tus puntuaciones Big Five. Así funciona: escalas Likert, ítems inversos, IRT y baremos de normalización.", "fr": "Vous répondez à 120 questions et des scores Big Five apparaissent. Le détail du calcul : échelles de Likert, items inversés, IRT, étalonnage.", "da": "Du svarer på 120 spørgsmål, og Big Five-scorer dukker op. Her er scoringen trin for trin: Likert, omvendt scoring, IRT og normering."}'::jsonb, updated_at = now()
