UPDATE blog_posts SET title = title || '{"ca": "Com dissenyar reunions per a totes les personalitats", "es": "Cómo diseñar reuniones para todas las personalidades", "fr": "Concevoir des réunions adaptées à chaque personnalité", "da": "Sådan designer du møder, der virker for alle"}'::jsonb, description = description || '{"ca": "Les reunions estàndard donen la paraula als més extravertits i silencien la resta. El Big Five mostra com redissenyar-les perquè hi càpiga tothom.", "es": "Las reuniones estándar dan la palabra a quien tiene Extraversión alta y callan al resto. Cómo rediseñarlas según la investigación Big Five.", "fr": "Les réunions classiques donnent la parole aux plus extravertis et taisent les autres. La recherche Big Five montre comment les repenser.", "da": "Standardmøder giver ordet til de mest ekstraverte og lukker munden på resten. Big Five-forskning viser, hvordan du bygger møder om for alle."}'::jsonb, updated_at = now()
