UPDATE blog_posts SET title = title || '{"ca": "Com donar feedback segons la personalitat de cadascú", "es": "Feedback informado por la personalidad: la evidencia", "fr": "Donner un feedback adapté à la personnalité : les preuves", "da": "Feedback tilpasset personligheden: hvad forskningen viser"}'::jsonb, description = description || '{"ca": "Més d''un terç de les intervencions de feedback empitjoren el rendiment. El Big Five prediu qui es bloca, qui assenteix i qui es desvincula.", "es": "Más de un tercio de las intervenciones de feedback empeoran el rendimiento. El Big Five predice quién se cierra y quién asiente sin cambiar nada.", "fr": "Plus d''un tiers des retours font baisser la performance. Le Big Five prédit qui se ferme, qui acquiesce, qui décroche. Adaptez votre façon de dire.", "da": "Over en tredjedel af al feedback sænker præstationen. Big Five forudsiger, hvem der lukker i, og hvem der nikker uden at ændre noget. Tilpas leveringen."}'::jsonb, updated_at = now()
