UPDATE blog_posts SET title = title || '{"ca": "Com llegir un informe Big Five: guia pràctica", "es": "Cómo leer un informe Big Five", "fr": "Comment lire un rapport Big Five : guide pratique", "da": "Sådan læser du din Big Five-rapport rigtigt"}'::jsonb, description = description || '{"ca": "Un informe Big Five són percentils, no etiquetes. Com llegir les puntuacions dels cinc trets, què vol dir alt i baix, i què no diuen els números.", "es": "Un informe Big Five son percentiles, no etiquetas. Cómo leer tus puntuaciones en los cinco rasgos y qué es lo que esos números no dicen.", "fr": "Un rapport Big Five, ce sont des percentiles, pas des étiquettes. Comment lire vos scores sur les cinq traits, et ce que les chiffres ne disent pas.", "da": "En Big Five-rapport er percentiler, ikke etiketter. Sådan læser du de fem træk, hvad højt og lavt betyder, og hvad tallene ikke fortæller dig."}'::jsonb, updated_at = now()
