UPDATE blog_posts SET title = title || '{"ca": "Usar dades de personalitat sense etiquetar les persones", "es": "Cómo usar datos de personalidad sin etiquetar a nadie", "fr": "Utiliser les données de personnalité sans étiqueter", "da": "Brug personlighedsdata uden at sætte etiketter på folk"}'::jsonb, description = description || '{"ca": "Les etiquetes congelen les persones en tipus i descarten el que diuen les puntuacions contínues. Fes servir el Big Five per conversar, no per jutjar.", "es": "Las etiquetas congelan a las personas en tipos y tiran lo que dicen las puntuaciones. Usa el Big Five para conversar, no para sentenciar.", "fr": "Les étiquettes figent les gens dans des types et jettent ce que disent les scores continus. Le Big Five ouvre une conversation, pas un verdict.", "da": "Etiketter fryser folk fast i typer og smider væk, hvad kontinuerte scorer rummer. Brug Big Five-data til en udviklingssamtale, ikke til en dom."}'::jsonb, updated_at = now()
