UPDATE blog_posts SET title = title || '{"ca": "Conflicte de personalitat en equips: com és realment", "es": "Conflicto de personalidad en equipos: cómo se ve de verdad", "fr": "Conflits de personnalité en équipe : à quoi ça ressemble", "da": "Personlighedskonflikter i teams: hvordan de ser ud"}'::jsonb, description = description || '{"ca": "El conflicte arrelat en diferències del Big Five sembla interpersonal, però és estructural. Vincle contra Disciplina, Visió contra Disciplina.", "es": "El conflicto por diferencias Big Five parece personal pero es estructural. Vínculo frente a Disciplina, Visión frente a Disciplina: nombra el patrón.", "fr": "Les conflits nés des différences Big Five semblent personnels mais sont structurels. Lien contre Discipline, Vision contre Discipline : nommez-les.", "da": "Teamkonflikter i Big Five-forskelle ser personlige ud, men er strukturelle. Tilknytning mod Disciplin, Vision mod Disciplin: navngiv mønstret."}'::jsonb, updated_at = now()
