UPDATE blog_posts SET title = title || '{"ca": "La personalitat i la crisi de replicació: què ha resistit", "es": "El Big Five y la crisis de replicación: qué resistió", "fr": "Big Five et crise de réplication : ce qui a résisté", "da": "Big Five og replikationskrisen: hvad har holdt stand?"}'::jsonb, description = description || '{"ca": "Només el 39% dels resultats de psicologia es van replicar el 2015. El Big Five va resistir molt millor, i el perquè diu de qui pots fiar-te.", "es": "Solo el 39% de los hallazgos psicológicos se replicó en 2015. El Big Five aguantó mucho mejor, y sus razones dicen en qué puedes confiar.", "fr": "Seuls 39 % des résultats en psychologie se sont répliqués en 2015. Le Big Five a bien mieux tenu, et l''on sait à quoi se fier aujourd''hui.", "da": "Kun 39 % af psykologiske fund replikerede i 2015. Big Five klarede sig langt bedre, og årsagerne viser, hvilke fund teams kan stole på."}'::jsonb, updated_at = now()
