UPDATE blog_posts SET title = title || '{"ca": "Per què 120 ítems superen 10 en un test de personalitat", "es": "Por qué 120 ítems ganan a 10 en un test de personalidad", "fr": "Pourquoi 120 items valent mieux que 10 : le compromis", "da": "Hvorfor 120 items slår 10: afvejningen i testlængde"}'::jsonb, description = description || '{"ca": "Els tests curts del Big Five arriben a una fiabilitat de 0,55 davant el 0,90 de 120 ítems. El compromís, i quan n''hi ha prou amb un de curt.", "es": "Los tests Big Five cortos llegan a una fiabilidad de 0,55 frente a 0,90 de los de 120 ítems. Este es el compromiso y cuándo basta con poco.", "fr": "Les tests Big Five courts plafonnent à 0,55 de fiabilité contre 0,90 à 120 items. Voici le compromis, et quand une version courte suffit."}'::jsonb, updated_at = now()
