UPDATE blog_posts SET title = title || '{"ca": "Per què les reunions esgoten unes persones i altres no", "es": "Por qué las reuniones agotan a unos y a otros no", "fr": "Pourquoi les réunions épuisent certains : la neuroscience", "da": "Hvorfor møder dræner nogle mere end andre: neurovidenskaben"}'::jsonb, description = description || '{"ca": "La fatiga de les reunions és neurobiològica. La teoria de l''activació d''Eysenck explica per què uns en surten esgotats i altres amb energia.", "es": "La fatiga de reunión es neurobiológica. La teoría de la activación de Eysenck explica por qué el introvertido sale agotado y el extravertido, lleno.", "fr": "La fatigue des réunions est neurobiologique. La théorie de l''activation d''Eysenck explique pourquoi les introvertis sortent vidés, les extravertis dopés.", "da": "Mødetræthed er neurobiologisk. Eysencks arousal-teori forklarer, hvorfor introverte forlader møder udmattede og ekstraverte energiske."}'::jsonb, updated_at = now()
 WHERE slug = 'why-meetings-drain-some-people-more-than-others-neuroscience';
UPDATE blog_posts SET title = title || '{"ca": "Per què l''autoavaluació sola no n''hi ha prou", "es": "Por qué la autoevaluación no basta: feedback de pares", "fr": "L''auto-évaluation ne suffit pas : le feedback des pairs", "da": "Hvorfor selvevaluering ikke er nok: feedback fra kolleger"}'::jsonb, description = description || '{"ca": "Les valoracions dels iguals comparteixen menys del 25% de la variància amb les autovaloracions del Big Five, i revelen punts cecs invisibles.", "es": "Las valoraciones de pares comparten menos del 25% de varianza con las propias en el Big Five. El feedback de colegas destapa puntos ciegos.", "fr": "Les pairs et vous partagez moins de 25 % de variance sur le Big Five. Leur retour révèle des angles morts qu''aucune auto-évaluation n''atteint.", "da": "Peer-vurderinger deler under 25 % af variansen med selvvurderinger i Big Five. Feedback fra kolleger afslører blinde pletter, du selv ikke ser."}'::jsonb, updated_at = now()
