UPDATE blog_posts SET title = title || '{"ca": "Personalitat i equilibri entre feina i vida: qui pateix", "es": "Conciliación y personalidad: quién lo lleva peor", "fr": "Équilibre travail-vie et personnalité : qui souffre le plus", "da": "Work-life balance og personlighed: hvem kæmper mest"}'::jsonb, description = description || '{"ca": "L''equilibri entre feina i vida no costa igual a tothom. El Big Five mostra que la Conscienciositat i el Neuroticisme creen el conflicte més intens.", "es": "Conciliar no cuesta lo mismo a todo el mundo. El Big Five muestra que la Responsabilidad y el Neuroticismo generan el conflicto más fuerte.", "fr": "L''équilibre travail-vie n''est pas également difficile pour tous. Le Big Five montre que la Conscienciosité et le Névrosisme pèsent le plus.", "da": "Work-life balance er ikke lige svær for alle. Big Five viser, at Samvittighedsfuldhed og Neuroticisme driver de stærkeste konflikter."}'::jsonb, updated_at = now()
 WHERE slug = 'work-life-balance-personality-who-struggles-most';

DO $$
DECLARE bad integer;
BEGIN
  SELECT count(*) INTO bad FROM blog_posts
   WHERE jsonb_typeof(title) <> 'object' OR jsonb_typeof(description) <> 'object';
  IF bad > 0 THEN RAISE EXCEPTION 'blog_posts: % row(s) with a non-object title or description', bad; END IF;

  -- Positive: every language is still readable on every row.
  SELECT count(*) INTO bad FROM blog_posts, unnest(ARRAY['en','ca','es','fr','de','da']) l
   WHERE (title->>l) IS NULL OR (description->>l) IS NULL;
  IF bad > 0 THEN RAISE EXCEPTION 'blog_posts: % row-language pair(s) with no title or description', bad; END IF;

  -- Negative: nothing over the display limit, and no dash of either width.
  SELECT count(*) INTO bad FROM blog_posts, unnest(ARRAY['en','ca','es','fr','de','da']) l
   WHERE length(title->>l) > 60 OR length(description->>l) > 155;
  IF bad > 0 THEN RAISE EXCEPTION 'blog_posts: % row-language pair(s) over the display limit', bad; END IF;

  -- The em dash is banned outright. The en dash is not: it is correct
  -- between the ends of a numeric range, and "r=.20-.40" written with a
  -- hyphen reads as a subtraction. What is banned is the en dash standing in
  -- for an em dash as sentence punctuation, which is the usage the rule is
  -- actually about, and that one always has a space beside it.
  SELECT count(*) INTO bad FROM blog_posts
   WHERE title::text ~ '\u2014' OR description::text ~ '\u2014'
      OR title::text ~ '(\s\u2013|\u2013\s)' OR description::text ~ '(\s\u2013|\u2013\s)';
  IF bad > 0 THEN RAISE EXCEPTION 'blog_posts: % row(s) with an em dash, or an en dash used as punctuation', bad; END IF;
END $$;

COMMIT;
